import "./App.css";
import { BrowserRouter, Navigate, Route, Routes } from "react-router-dom";
import { useAuth } from "./Pages/Auth/AuthContext";
import LoginSignUp from "./Pages/Auth/Signup";
import PrivateRoute from "./Pages/Auth/PrivateRoute";
import Dashboard from "./Pages/Home/Dashboard";
import Profile from "./Pages/Profile/Profile";
import ImageHoverTracker from "./Pages/UserTask/UserTask";
import Home from "./Pages/Lander/Home";
import Progress from "./Pages/Feedback/Progress";
import Rewards from "./Pages/Rewards/Rewards";
import Tutorial from "./Pages/Tutorial/Tutorial";
import CannabisSurvey from "./Pages/Auth/Survey";
import { HashRouter } from "react-router-dom";

function App() {
  const { isAuthenticated } = useAuth();
  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/auth" element={<LoginSignUp />} />
        <Route path="/survey" element={<CannabisSurvey />} />
        <Route
          path="/dashboard"
          element={
            <PrivateRoute>
              <Dashboard />
            </PrivateRoute>
          }
        />
        <Route
          path="/profile"
          element={
            <PrivateRoute>
              <Profile />
            </PrivateRoute>
          }
        />
        <Route
          path="/progress"
          element={
            <PrivateRoute>
              <Progress />
            </PrivateRoute>
          }
        />
        <Route
          path="/rewards"
          element={
            <PrivateRoute>
              <Rewards />
            </PrivateRoute>
          }
        />
        <Route
          path="/tutorial"
          element={
            <PrivateRoute>
              <Tutorial />
            </PrivateRoute>
          }
        />
        <Route
          path="/user-task"
          element={<ImageHoverTracker />}
        />
        <Route
          path="/"
          element={<Navigate to={isAuthenticated ? "/dashboard" : "/"} />}
        />
      </Routes>
    </HashRouter>
  );
}

export default App;

